"""Verify the network directive, so the controller's DNS zone follows a move.

The controller owns the DNS records for every gateway subdomain. If the network
moves to a new domain and the controller keeps writing `gw*.old-domain`, the
gateways come up under a name nothing points at any more -- so the zone has to
follow the directive rather than a value baked into a ConfigMap.

WHY THE SIGNATURE IS CHECKED HERE AT ALL
The controller runs beside the origin and is operated by the same person, so it
would be easy to argue it can just believe what the origin tells it. But this
service holds the credentials that rewrite DNS for every gateway in the network.
A document that redirects that, accepted without a signature, is the most
valuable thing in the system to forge. It costs little to check.

WHY THE CURVE MATHS IS IN THIS FILE
The controller's dependencies are FastAPI, SQLAlchemy, PyNaCl and base58. PyNaCl
is Ed25519; nothing here speaks secp256k1, and adding an Ethereum stack to a
service whose whole job is writing DNS records is a large new surface for one
signature check.

Pure Python is safe for THIS operation specifically: recovery handles a public
key, a public message and a public signature. No secret is processed, so the
constant-time argument that rules out hand-rolled crypto elsewhere does not
apply. The same reasoning already produced backend/services/keccak.py, written
because that runtime had no keccak either.

Cross-checked against fixtures generated by the Go implementation, including the
well-known vector: private key 1 recovers to 0x7e5f...5bdf.
"""

from __future__ import annotations

import hashlib
import re
from typing import Iterable

# secp256k1.
_P = 2**256 - 2**32 - 977
_N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
_GX = 0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798
_GY = 0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8

Point = tuple[int, int] | None  # None is the point at infinity

HEADER = "syndichan network directive v1"
SIGNED_FIELDS = (
    "kind", "sequence", "issued_at", "not_before", "emergency",
    "origin_domain", "origin_address", "origin_key", "note",
)
_ADDRESS = re.compile(r"^0x[0-9a-f]{40}$")


# -- keccak-256 ------------------------------------------------------------
#
# NOT hashlib.sha3_256. SHA-3 pads with 0x06 where keccak pads with 0x01, so
# they are different functions with the same block structure -- close enough to
# look right and never produce a matching address.

_KECCAK_ROUNDS = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808A,
    0x8000000080008000, 0x000000000000808B, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008A,
    0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
    0x000000008000808B, 0x800000000000008B, 0x8000000000008089,
    0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
    0x000000000000800A, 0x800000008000000A, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
]
_KECCAK_ROTATIONS = [
    [0, 36, 3, 41, 18], [1, 44, 10, 45, 2], [62, 6, 43, 15, 61],
    [28, 55, 25, 21, 56], [27, 20, 39, 8, 14],
]
_MASK = (1 << 64) - 1


def _rotl(value: int, shift: int) -> int:
    return ((value << shift) | (value >> (64 - shift))) & _MASK


def _keccak_f(state: list[list[int]]) -> None:
    for rc in _KECCAK_ROUNDS:
        c = [state[x][0] ^ state[x][1] ^ state[x][2] ^ state[x][3] ^ state[x][4]
             for x in range(5)]
        d = [c[(x - 1) % 5] ^ _rotl(c[(x + 1) % 5], 1) for x in range(5)]
        for x in range(5):
            for y in range(5):
                state[x][y] ^= d[x]
        b = [[0] * 5 for _ in range(5)]
        for x in range(5):
            for y in range(5):
                b[y][(2 * x + 3 * y) % 5] = _rotl(state[x][y], _KECCAK_ROTATIONS[x][y])
        for x in range(5):
            for y in range(5):
                state[x][y] = b[x][y] ^ (~b[(x + 1) % 5][y] & _MASK
                                         & b[(x + 2) % 5][y])
        state[0][0] ^= rc


def keccak256(data: bytes) -> bytes:
    rate = 136  # 1088 bits, the rate for keccak-256
    state = [[0] * 5 for _ in range(5)]
    padded = bytearray(data)
    padded.append(0x01)  # keccak padding, NOT SHA-3's 0x06
    while len(padded) % rate != 0:
        padded.append(0x00)
    padded[-1] |= 0x80

    for offset in range(0, len(padded), rate):
        block = padded[offset:offset + rate]
        for i in range(rate // 8):
            lane = int.from_bytes(block[i * 8:(i + 1) * 8], "little")
            state[i % 5][i // 5] ^= lane
        _keccak_f(state)

    out = bytearray()
    for i in range(4):  # 32 bytes
        out += state[i % 5][i // 5].to_bytes(8, "little")
    return bytes(out[:32])


# -- curve -----------------------------------------------------------------

def _inverse(value: int, modulus: int) -> int:
    return pow(value, modulus - 2, modulus)


def _add(a: Point, b: Point) -> Point:
    if a is None:
        return b
    if b is None:
        return a
    ax, ay = a
    bx, by = b
    if ax == bx:
        if (ay + by) % _P == 0:
            return None
        slope = (3 * ax * ax) * _inverse(2 * ay, _P) % _P
    else:
        slope = (by - ay) * _inverse(bx - ax, _P) % _P
    x = (slope * slope - ax - bx) % _P
    return (x, (slope * (ax - x) - ay) % _P)


def _multiply(point: Point, scalar: int) -> Point:
    result: Point = None
    addend = point
    while scalar:
        if scalar & 1:
            result = _add(result, addend)
        addend = _add(addend, addend)
        scalar >>= 1
    return result


def _personal_hash(message: str) -> int:
    body = message.encode("utf-8")
    prefixed = b"\x19Ethereum Signed Message:\n%d%s" % (len(body), body)
    return int.from_bytes(keccak256(prefixed), "big")


def recover_signer(message: str, signature: str) -> str | None:
    """The 0x address that produced an EIP-191 signature, or None."""
    raw = (signature or "").strip()
    if raw.startswith("0x") or raw.startswith("0X"):
        raw = raw[2:]
    try:
        blob = bytes.fromhex(raw)
    except ValueError:
        return None
    if len(blob) != 65:
        return None

    r = int.from_bytes(blob[0:32], "big")
    s = int.from_bytes(blob[32:64], "big")
    v = blob[64]
    if v >= 27:
        v -= 27
    if v > 1 or not (0 < r < _N) or not (0 < s < _N):
        return None

    # Reject the high-s half. Every signature has a valid low-s twin, so
    # accepting both means two distinct signatures over one message -- which
    # turns "have I already seen this directive?" into a question with no
    # reliable answer.
    if s > _N // 2:
        return None

    # R from r and the recovery parity.
    y_squared = (pow(r, 3, _P) + 7) % _P
    y = pow(y_squared, (_P + 1) // 4, _P)
    if (y * y - y_squared) % _P != 0:
        return None  # r was not a valid x coordinate
    if y % 2 != v % 2:
        y = _P - y

    z = _personal_hash(message)
    r_inverse = _inverse(r, _N)
    point = _multiply(_add(_multiply((r, y), s),
                           _multiply((_GX, _GY), _N - (z % _N))), r_inverse)
    if point is None:
        return None
    x, y = point
    digest = keccak256(x.to_bytes(32, "big") + y.to_bytes(32, "big"))
    return "0x" + digest[12:].hex()


def same_address(a: str | None, b: str | None) -> bool:
    """Case-insensitive address comparison.

    Two empty strings must NOT match: that is the shape of a controller with no
    pinned wallet accepting whatever arrives.
    """
    a = (a or "").strip().lower()
    b = (b or "").strip().lower()
    return bool(a) and bool(b) and a == b


# -- the document ----------------------------------------------------------

def canonical(directive: dict) -> str:
    """The signed bytes. Must match backend/services/network_directive.py and
    storage-client/internal/directive exactly."""
    lines = [HEADER]
    for field in SIGNED_FIELDS:
        value = directive.get(field)
        if value is None or value == "":
            value = "-"
        elif value is True:
            value = "yes"
        elif value is False:
            value = "no"
        lines.append("%s: %s" % (field, value))
    return "\n".join(lines)


def verify_document(document: dict, pinned_wallet: str,
                    held_sequence: int = 0) -> dict | None:
    """The directive in a served document, if it verifies and is newer.

    Returns None rather than raising: this runs in a scheduled DNS sync, and a
    controller that crashed on a malformed document would stop maintaining
    records for every gateway in the network because one fetch was bad.
    """
    directive = (document or {}).get("directive")
    if not isinstance(directive, dict):
        return None

    # Rebuilt from the signed fields, never taken from the served text. A
    # document whose `canonical` disagrees with its own fields would otherwise
    # let one valid signature vouch for values nobody signed.
    directive = {field: directive.get(field) for field in SIGNED_FIELDS}
    message = canonical(directive)
    served = (document or {}).get("canonical")
    if served and served != message:
        return None

    if not _ADDRESS.match((pinned_wallet or "").strip().lower()):
        return None
    signer = recover_signer(message, (document or {}).get("signature") or "")
    if not same_address(signer, pinned_wallet):
        return None

    try:
        sequence = int(directive.get("sequence") or 0)
    except (TypeError, ValueError):
        return None
    if sequence <= int(held_sequence or 0):
        return None
    return directive


def zone_from(directive: dict | None, configured: str) -> str:
    """The DNS zone the controller should manage.

    Only a move changes it. A freeze pins the network where it is, and reading
    that as a move to nowhere would have the controller manage an empty zone --
    deleting every gateway record in the network.
    """
    if not directive or directive.get("kind") != "move":
        return configured
    domain = (directive.get("origin_domain") or "").strip().lower()
    return domain or configured


def is_effective(directive: dict | None, now: int) -> bool:
    if not directive:
        return False
    try:
        return now >= int(directive.get("not_before") or 0)
    except (TypeError, ValueError):
        return False


def sources(configured_domain: str, extra: Iterable[str] = ()) -> list[str]:
    """Where to look for the document, current domain first."""
    found = ["https://%s/.well-known/syndichan/network.json" % configured_domain]
    for candidate in extra:
        candidate = (candidate or "").strip()
        if candidate and candidate not in found:
            found.append(candidate)
    return found
